function fun = create_soft_size_checker(get_max_rads, dims_to_check, maximum_relative_growth)

    % The criterion w.r.t. the hierarchical dim should be chosen in such a way
    % that two boxes generated by base_divider with different centers in the
    % hierarchical dim are never merged.
    function [res, set_union] = check_sizes(sets, max_rads_of_merged_sets)
        res = false;
        set_union = [];

        c_mean = mean(cell2mat(cellfun(@(s) s.c, sets, 'UniformOutput', false)), 2);
        max_rads = get_max_rads(c_mean);

        itv_union = fold(@(a, b) a.enclosing_itv | b.enclosing_itv, sets);
        if ~check_size_for_union(itv_union, dims_to_check, max_rads, ...
                max_rads_of_merged_sets, maximum_relative_growth)
            return
        end

        %% Hint: the normal union with the or-operator throws some
        %% out-of-bound exception for zonotopes of our size, and the convHull
        %% is usually a quite large overapproximation.
        % set_union_old = fold(@(a, b) convHull(a.cora_set, b.cora_set), sets);
        % set_union_old = reduce(set_union_old, 'pca', 50);

        max_enlargement = maximum_relative_growth;
        rads_1 = rad(sets{1}.enclosing_itv);
        rads_1 = rads_1(dims_to_check);
        max_possible_rad_growth = min((max_rads - rads_1) ./ rads_1);
        max_enlargement = 1.0 + max(max_enlargement, max_possible_rad_growth);
        set_union = fold(@(a, b) merge_zonotopes(a.cora_set, b.cora_set, max_enlargement), sets);

        if is_empty_var(set_union)
            return
        end
        res = check_size_for_union(set_union, dims_to_check, ...
            max_rads, max_rads_of_merged_sets, maximum_relative_growth);
    end

    fun = @check_sizes;
end

function res = check_size_for_union(set_union, dims_to_check, max_rads, ...
    max_rad_sets, maximum_relative_growth)
    res = false;
    set_union_itv = interval(set_union);
    for i = 1:length(dims_to_check)
        dim = dims_to_check(i);
        set_union_proj = project(set_union_itv, dim);
        r = rad(set_union_proj);

        % We merge sets if
        % 1) the union is small enough, or
        % 2) the relative growth is not too large.
        % Idea: Criterion 1) ensures that - if a dimension d is controlled
        % very well such that the final set is always small in d - we still
        % merge as a larger initial range in d is ok. Only using criterion
        % 2) would prevent merging in this case.
        % Criterion 2), on the other hand, ensures that we merge if the size
        % of the union is only slightly larger than the size of one of the sets.
        criterion_1 = r <= max_rads(i);
        if ~criterion_1
            max_rad_sets_dim = max_rad_sets(dim);
            criterion_2 = r <= (1 + maximum_relative_growth) * max_rad_sets_dim;
            if ~criterion_2
                return
            end
        end
    end
    res = true;
end
